    AIMessage(content='', additional_kwargs={}, response_metadata={'model_provider': 'deepseek', 'finish_reason': 'tool_calls', 'model_name': 'deepseek-v4-flash', 'system_fingerprint': 'fp_8b330d02d0_prod0820_fp8_kvcache_20260402'}, name='coder_node', id='lc_run--019f504b-ef4a-79f0-abe5-ba886bb5ecf6', tool_calls=[{'name': 'create_file', 'args': {'content': '"""\n种子管理模块\n实现确定性复现：字符串种子统一 hash 转为整数种子\n规则：\n- int 种子范围：1 ~ 999999999\n- str 种子：长度 1~32，仅字母数字，非法字符自动清洗\n- 非法种子：自动生成 6 位随机数字兜底\n- 所有随机行为统一绑定同一个种子，保证全局确定性\n"""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport random\nimport re\nimport time\nfrom typing import Optional\n\n\nclass SeedManager:\n    """种子管理器，保证全局随机确定性"""\n\n    def __init__(self, seed: Optional[str | int] = None):\n        self._seed: int = 0\n        self._raw_seed: str = ""\n        self._rng: random.Random = random.Random()\n        self.set_seed(seed)\n\n    def set_seed(self, seed: Optional[str | int] = None) -> None:\n        """设置种子，支持 int 或 str 类型"""\n        if seed is None:\n            # 自动生成 6 位随机数字兜底\n            fallback = int(time.time() * 1000) % 1000000\n            self._raw_seed = str(fallback)\n            self._seed = fallback\n        elif isinstance(seed, int):\n            self._seed = self._normalize_int_seed(seed)\n            self._raw_seed = str(self._seed)\n        elif isinstance(seed, str):\n            self._raw_seed = seed\n            self._seed = self._str_to_int_seed(seed)\n        else:\n            fallback = int(time.time() * 1000) % 1000000\n            self._raw_seed = str(fallback)\n            self._seed = fallback\n\n        self._rng = random.Random(self._seed)\n\n    def _normalize_int_seed(self, seed: int) -> int:\n        """规范化整数种子到 1~999999999 范围"""\n        if seed < 1:\n            seed = abs(seed) % 999999999 + 1\n        if seed > 999999999:\n            seed = seed % 999999999 + 1\n        return seed\n\n    def _str_to_int_seed(self, seed_str: str) -> int:\n        """字符串种子统一 hash 转为整数种子"""\n        # 清洗：仅保留字母数字\n        cleaned = re.sub(r\'[^a-zA-Z0-9]\', \'\', seed_str)\n        if not cleaned or len(cleaned) > 32:\n            # 非法种子，自动生成 6 位随机数字兜底\n            fallback = int(time.time() * 1000) % 1000000\n            return fallback\n        # 使用 hashlib 将字符串 hash 为整数\n        hash_bytes = hashlib.sha256(cleaned.encode(\'utf-8\')).digest()\n        hash_int = int.from_bytes(hash_bytes[:4], byteorder=\'big\')\n        return self._normalize_int_seed(hash_int)\n\n    @property\n    def seed(self) -> int:\n        """获取当前整数种子"""\n        return self._seed\n\n    @property\n    def raw_seed(self) -> str:\n        """获取原始种子字符串"""\n        return self._raw_seed\n\n    @property\n    def rng(self) -> random.Random:\n        """获取绑定的随机数生成器"""\n        return self._rng\n\n    def randint(self, a: int, b: int) -> int:\n        """生成 [a, b] 范围内的随机整数"""\n        return self._rng.randint(a, b)\n\n    def random(self) -> float:\n        """生成 [0.0, 1.0) 范围内的随机浮点数"""\n        return self._rng.random()\n\n    def choice(self, seq: list) -> any:\n        """从序列中随机选择一个元素"""\n        return self._rng.choice(seq)\n\n    def shuffle(self, seq: list) -> None:\n        """随机打乱序列"""\n        self._rng.shuffle(seq)\n', 'file_path': 'generated/seed_manager.py'}, 'id': 'call_00_Lb6P8rgmKVaZLdzfa9Eq1776', 'type': 'tool_call'}], invalid_tool_calls=[], usage_metadata={'input_tokens': 8196, 'output_tokens': 946, 'total_tokens': 9142, 'input_token_details': {'cache_read': 8064}, 'output_token_details': {}}), 
    
