    AIMessage(content='', additional_kwargs={}, response_metadata={'model_provider': 'deepseek', 'finish_reason': 'tool_calls', 'model_name': 'deepseek-v4-flash', 'system_fingerprint': 'fp_8b330d02d0_prod0820_fp8_kvcache_20260402'}, name='coder_node', id='lc_run--019f504c-0835-7d83-9bb6-125902f4512d', tool_calls=[{'name': 'create_file', 'args': {'content': '"""\n抽象基类 BaseGenerator\n统一接口：generate() -> 输出 tile_map, start, end, room_list\n"""\n\nfrom __future__ import annotations\n\nfrom abc import ABC, abstractmethod\nfrom typing import Optional\n\nfrom models import MapBasicConfig, MapFullData, Position\nfrom seed_manager import SeedManager\n\n\nclass BaseGenerator(ABC):\n    """所有地图生成算法的抽象基类"""\n\n    def __init__(self, config: MapBasicConfig, seed_manager: Optional[SeedManager] = None):\n        self.config = config\n        self.seed_manager = seed_manager or SeedManager()\n\n    @abstractmethod\n    def generate(self) -> MapFullData:\n        """\n        执行地图生成\n\n        Returns:\n            MapFullData: 包含 tile_map, start, end, room_list 等完整地图数据\n        """\n        pass\n\n    def _create_empty_tile_layer(self, width: int, height: int) -> list[list[int]]:\n        """创建空的地图层（全部为地面）"""\n        return [[0 for _ in range(width)] for _ in range(height)]\n\n    def _is_valid_position(self, x: int, y: int, width: int, height: int) -> bool:\n        """检查坐标是否在地图范围内"""\n        return 0 <= x < width and 0 <= y < height\n\n    def _bfs_check_connectivity(\n        self,\n        tile_layer: list[list[int]],\n        start: Position,\n        end: Position,\n        width: int,\n        height: int,\n    ) -> bool:\n        """\n        BFS 连通性校验：起点到终点必须存在通路\n        可通行地块：tile == 0 (GROUND)\n        """\n        if tile_layer[start.y][start.x] != 0:\n            return False\n        if tile_layer[end.y][end.x] != 0:\n            return False\n\n        visited = [[False] * width for _ in range(height)]\n        from collections import deque\n\n        queue = deque()\n        queue.append((start.x, start.y))\n        visited[start.y][start.x] = True\n\n        # 四方向移动\n        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]\n\n        while queue:\n            cx, cy = queue.popleft()\n            if cx == end.x and cy == end.y:\n                return True\n            for dx, dy in directions:\n                nx, ny = cx + dx, cy + dy\n                if self._is_valid_position(nx, ny, width, height):\n                    if not visited[ny][nx] and tile_layer[ny][nx] == 0:\n                        visited[ny][nx] = True\n                        queue.append((nx, ny))\n\n        return False\n', 'file_path': 'generated/base_generator.py'}, 'id': 'call_00_LwkkRM8g0LQI15oFMOy21539', 'type': 'tool_call'}], invalid_tool_calls=[], usage_metadata={'input_tokens': 9176, 'output_tokens': 650, 'total_tokens': 9826, 'input_token_details': {'cache_read': 9088}, 'output_token_details': {}}), 
    
