    AIMessage(content='', additional_kwargs={}, response_metadata={'model_provider': 'deepseek', 'finish_reason': 'tool_calls', 'model_name': 'deepseek-v4-flash', 'system_fingerprint': 'fp_8b330d02d0_prod0820_fp8_kvcache_20260402'}, name='coder_node', id='lc_run--019f504c-1a4b-73d0-90e2-e4594638b7b0', tool_calls=[{'name': 'create_file', 'args': {'content': '"""\nGridRandom 网格随机算法实现\n\n适用：小型闯关、小游戏地图\n逻辑：根据 wallRatio / trapMaxRatio 逐地块随机生成，保证基础通路，最后 BFS 校验通路。\n\n算法步骤：\n1. 根据配置确定地图尺寸\n2. 逐地块随机生成墙壁（wallRatio 控制墙壁占比）\n3. 随机放置陷阱（trapMaxRatio 控制陷阱最大占比）\n4. 随机选取起点和终点（必须为可通行地面）\n5. BFS 校验起点到终点连通性\n6. 若不连通则重试，直到达到最大重试次数\n"""\n\nfrom __future__ import annotations\n\nimport time\nfrom typing import Optional\n\nfrom base_generator import BaseGenerator\nfrom models import (\n    MapBasicConfig,\n    MapFullData,\n    Position,\n    TileType,\n)\nfrom seed_manager import SeedManager\n\n\nclass GridRandomGenerator(BaseGenerator):\n    """网格随机算法生成器"""\n\n    def __init__(\n        self,\n        config: Optional[MapBasicConfig] = None,\n        seed_manager: Optional[SeedManager] = None,\n        max_retry_times: int = 5,\n    ):\n        super().__init__(config or MapBasicConfig(), seed_manager)\n        self.max_retry_times = max_retry_times\n\n    def generate(self) -> MapFullData:\n        """\n        执行网格随机地图生成\n\n        Returns:\n            MapFullData: 完整地图数据\n        """\n        start_time = time.time()\n\n        # 1. 确定地图尺寸\n        width, height = self._resolve_map_size()\n\n        # 2. 计算墙壁和陷阱数量\n        total_cells = width * height\n        wall_count = int(total_cells * self.config.wallRatio / 100)\n        trap_max_count = int(total_cells * self.config.trapMaxRatio / 100)\n\n        retry_count = 0\n        result: Optional[MapFullData] = None\n\n        while retry_count <= self.max_retry_times:\n            # 重置随机状态（每次重试使用不同随机序列）\n            if retry_count > 0:\n                # 重试时偏移种子，避免无限相同结果\n                offset_seed = self.seed_manager.seed + retry_count * 1000\n                temp_rng = SeedManager(offset_seed)\n            else:\n                temp_rng = self.seed_manager\n\n            # 3. 生成 tile_layer\n            tile_layer = self._generate_tile_layer(\n                width, height, wall_count, trap_max_count, temp_rng\n            )\n\n            # 4. 选取起点和终点\n            start_pos, end_pos = self._pick_start_end(\n                tile_layer, width, height, temp_rng\n            )\n\n            if start_pos is None or end_pos is None:\n                retry_count += 1\n                continue\n\n            # 5. BFS 校验连通性\n            if self._bfs_check_connectivity(tile_layer, start_pos, end_pos, width, height):\n                # 生成成功\n                elapsed_ms = (time.time() - start_time) * 1000\n                result = MapFullData(\n                    seed=self.seed_manager.raw_seed,\n                    mapWidth=width,\n                    mapHeight=height,\n                    tileLayer=tile_layer,\n                    startPos=start_pos,\n                    endPos=end_pos,\n                    roomList=[],\n                    monsterData=[],\n                    itemData=[],\n                    chestData=[],\n                    trapData=[],\n                    generateCostMs=round(elapsed_ms, 2),\n                    retryCount=retry_count,\n                    checkPass=True,\n                )\n                break\n\n            retry_count += 1\n\n        if result is None:\n            # 所有重试均失败，返回最后一次尝试的结果（未通过校验）\n            elapsed_ms = (time.time() - start_time) * 1000\n            result = MapFullData(\n                seed=self.seed_manager.raw_seed,\n                mapWidth=width,\n                mapHeight=height,\n                tileLayer=tile_layer if \'tile_layer\' in dir() else self._create_empty_tile_layer(width, height),\n                startPos=start_pos,\n                endPos=end_pos,\n                roomList=[],\n                monsterData=[],\n                itemData=[],\n                chestData=[],\n                trapData=[],\n                generateCostMs=round(elapsed_ms, 2),\n                retryCount=retry_count,\n                checkPass=False,\n            )\n\n        return result\n\n    def _resolve_map_size(self) -> tuple[int, int]:\n        """解析地图尺寸（支持固定尺寸和随机尺寸）"""\n        if self.config.isRandomSize:\n            w = self.seed_manager.randint(self.config.widthRange[0], self.config.widthRange[1])\n            h = self.seed_manager.randint(self.config.heightRange[0], self.config.heightRange[1])\n            return w, h\n        return self.config.width, self.config.height\n\n    def _generate_tile_layer(\n        self,\n        width: int,\n        height: int,\n        wall_count: int,\n        trap_max_count: int,\n        rng: SeedManager,\n    ) -> list[list[int]]:\n        """\n        逐地块随机生成地图\n\n        策略：\n        1. 先全部初始化为地面\n        2. 随机选取 wall_count 个位置设为墙壁\n        3. 随机选取 trap_max_count 个位置设为陷阱（避开墙壁）\n        """\n        # 初始化全部为地面\n        tile_layer = self._create_empty_tile_layer(width, height)\n\n        # 收集所有可用的坐标池\n        all_positions = [(x, y) for y in range(height) for x in range(width)]\n        rng.shuffle(all_positions)\n\n        # 放置墙壁\n        wall_positions = set()\n        for i in range(min(wall_count, len(all_positions))):\n            x, y = all_positions[i]\n            tile_layer[y][x] = TileType.WALL.value\n            wall_positions.add((x, y))\n\n        # 放置陷阱（避开墙壁位置）\n        # 从剩余的非墙壁位置中随机选取\n        non_wall_positions = [p for p in all_positions if p not in wall_positions]\n        rng.shuffle(non_wall_positions)\n\n        trap_count = rng.randint(0, trap_max_count)\n        for i in range(min(trap_count, len(non_wall_positions))):\n            x, y = non_wall_positions[i]\n            tile_layer[y][x] = TileType.TRAP.value\n\n        return tile_layer\n\n    def _pick_start_end(\n        self,\n        tile_layer: list[list[int]],\n        width: int,\n        height: int,\n        rng: SeedManager,\n    ) -> tuple[Optional[Position], Optional[Position]]:\n        """\n        选取起点和终点\n        起点：地图左上区域的可通行地面\n        终点：地图右下区域的可通行地面\n        起点和终点不能相同\n        """\n        # 收集所有可通行地面坐标\n        ground_positions = []\n        for y in range(height):\n            for x in range(width):\n                if tile_layer[y][x] == TileType.GROUND.value:\n                    ground_positions.append((x, y))\n\n        if len(ground_positions) < 2:\n            return None, None\n\n        rng.shuffle(ground_positions)\n\n        # 起点偏向左上区域\n        start_candidates = [\n            (x, y) for x, y in ground_positions\n            if x < width // 2 and y < height // 2\n        ]\n        if not start_candidates:\n            start_candidates = ground_positions\n\n        # 终点偏向右下区域\n        end_candidates = [\n            (x, y) for x, y in ground_positions\n            if x >= width // 2 and y >= height // 2\n        ]\n        if not end_candidates:\n            end_candidates = ground_positions\n\n        start_x, start_y = rng.choice(start_candidates)\n        end_x, end_y = rng.choice(end_candidates)\n\n        # 确保起点和终点不同\n        if start_x == end_x and start_y == end_y:\n            # 尝试换一个终点\n            other_ends = [p for p in end_candidates if p != (start_x, start_y)]\n            if other_ends:\n                end_x, end_y = rng.choice(other_ends)\n            else:\n                # 尝试换一个起点\n                other_starts = [p for p in start_candidates if p != (start_x, start_y)]\n                if other_starts:\n                    start_x, start_y = rng.choice(other_starts)\n                else:\n                    return None, None\n\n        return Position(x=start_x, y=start_y), Position(x=end_x, y=end_y)\n', 'file_path': 'generated/grid_random_generator.py'}, 'id': 'call_00_ZEct6ei7TJOE6QLZ5L5F6686', 'type': 'tool_call'}], invalid_tool_calls=[], usage_metadata={'input_tokens': 9861, 'output_tokens': 1977, 'total_tokens': 11838, 'input_token_details': {'cache_read': 9728}, 'output_token_details': {}}), 
    
